      this.tail = nodeToAdd
    } else {
      this.tail.next = nodeToAdd
      this.tail = nodeToAdd
    }
    this.length++
    return this
  }

  reverse() {
    let current = this.head
    this.head = this.tail
    this.tail = current
    let previous = null
    let nextNode = null
    for (let i = 0; i < this.length; i++) {
      nextNode = current.next
      current.next = previous
      previous = current
      current = nextNode
    }
    return this
  }

  // our helper: the values from head to tail, as an array
  toArray() {
    const values = []
    let current = this.head
    while (current !== null) {
      values.push(current.value)
      current = current.next
    }
    return values
  }
